class ExpressionParser:
    """A simple recursive descent parser to evaluate arithmetic expressions."""

    def __init__(self, expression: str):
        self.expression = expression.replace(' ', '')
        self.position = 0
        self.current_char = self.expression[self.position] if self.expression else None

    def error(self):
        raise Exception("Invalid syntax")

    def advance(self):
        """Advance the `position` pointer and update `current_char`."""
        self.position += 1
        self.current_char = self.expression[self.position] if self.position < len(self.expression) else None

    def skip_whitespace(self):
        """Skip whitespace characters."""
        while self.current_char is not None and self.current_char.isspace():
            self.advance()

    def number(self) -> float:
        """Return a floating-point number from the expression."""
        result = ''
        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            result += self.current_char
            self.advance()
        return float(result)

    def factor(self) -> float:
        """Return a factor (number or sub-expression in parentheses)."""
        if self.current_char == '(':
            self.advance()  # Skip '('
            result = self.expr()
            if self.current_char == ')':
                self.advance()  # Skip ')'
                return result
            else:
                self.error()
        elif self.current_char.isdigit() or self.current_char == '.':
            return self.number()
        else:
            self.error()

    def term(self) -> float:
        """Return a term (factor or product of factors)."""
        result = self.factor()
        while self.current_char is not None and self.current_char in ('*', '/'):
            if self.current_char == '*':
                self.advance()
                result *= self.factor()
            elif self.current_char == '/':
                self.advance()
                divisor = self.factor()
                if divisor == 0:
                    self.error()  # Handle division by zero
                result /= divisor
        return result

    def expr(self) -> float:
        """Return the final result calculated from the expression."""
        result = self.term()
        while self.current_char is not None and self.current_char in ('+', '-'):
            if self.current_char == '+':
                self.advance()
                result += self.term()
            elif self.current_char == '-':
                self.advance()
                result -= self.term()
        return result

def evaluate(expr: str) -> float:
    """Evaluates a given arithmetic expression respecting standard operator precedence."""
    parser = ExpressionParser(expr)
    return parser.expr()

class ShuntingYard:
    """Implement the Shunting Yard algorithm to parse and evaluate arithmetic expressions using a stack-based approach."""

    def __init__(self, expression: str):
        self.expression = expression.replace(" ", "")
        self.output_queue = []
        self.operator_stack = []

    def precedence(self, op: str) -> int:
        """Return the precedence level of an operator."""
        if op in ('+', '-'):
            return 1
        elif op in ('*', '/'):
            return 2
        return 0

    def apply_operator(self, op: str):
        """Apply an operator to the top two values in the output queue."""
        right = self.output_queue.pop()
        left = self.output_queue.pop()
        if op == '+':
            self.output_queue.append(left + right)
        elif op == '-':
            self.output_queue.append(left - right)
        elif op == '*':
            self.output_queue.append(left * right)
        elif op == '/':
            if right == 0:
                raise ZeroDivisionError("division by zero")
            self.output_queue.append(left / right)

    def parse_number(self, start: int) -> (float, int):
        """Extract a number from the expression starting at the given position."""
        end = start
        while end < len(self.expression) and (self.expression[end].isdigit() or self.expression[end] == '.'):
            end += 1
        number = float(self.expression[start:end])
        return number, end

    def parse(self):
        """Parse the expression into output queue and operator stack."""
        idx = 0
        while idx < len(self.expression):
            char = self.expression[idx]
            if char.isdigit() or char == '.':
                num, idx = self.parse_number(idx)
                self.output_queue.append(num)
            elif char in ('+', '-', '*', '/'):
                while (self.operator_stack and
                       self.precedence(self.operator_stack[-1]) >= self.precedence(char)):
                    self.apply_operator(self.operator_stack.pop())
                self.operator_stack.append(char)
                idx += 1
            elif char == '(':
                self.operator_stack.append(char)
                idx += 1
            elif char == ')':
                while self.operator_stack and self.operator_stack[-1] != '(':
                    self.apply_operator(self.operator_stack.pop())
                self.operator_stack.pop()  # Pop the '('
                idx += 1

        while self.operator_stack:
            self.apply_operator(self.operator_stack.pop())

    def evaluate(self) -> float:
        """Return the final result from the output queue."""
        return self.output_queue[0] if self.output_queue else 0.0


def evaluate(expr: str) -> float:
    """Evaluates a given arithmetic expression using the Shunting Yard algorithm."""
    parser = ShuntingYard(expr)
    parser.parse()
    return parser.evaluate()

def evaluate(expr: str) -> float:
    """Evaluate an arithmetic expression using the Shunting Yard algorithm for parsing and a Reverse Polish Notation (RPN) approach for evaluation."""

    def shunting_yard(expression):
        output = []
        operators = []
        precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
        i = 0
        length = len(expression)

        def is_operator(c):
            return c in precedence

        while i < length:
            if expression[i].isdigit() or expression[i] == '.':
                num = ''
                while i < length and (expression[i].isdigit() or expression[i] == '.'):
                    num += expression[i]
                    i += 1
                output.append(float(num))
                continue
            elif expression[i] == '(':
                operators.append(expression[i])
            elif expression[i] == ')':
                while operators and operators[-1] != '(':
                    output.append(operators.pop())
                operators.pop()  # Remove '('
            elif is_operator(expression[i]):
                while (operators and operators[-1] != '(' and
                       precedence[operators[-1]] >= precedence[expression[i]]):
                    output.append(operators.pop())
                operators.append(expression[i])
            i += 1

        while operators:
            output.append(operators.pop())

        return output

    def evaluate_rpn(rpn):
        stack = []
        for token in rpn:
            if isinstance(token, float):
                stack.append(token)
            else:
                b = stack.pop()
                a = stack.pop()
                if token == '+':
                    stack.append(a + b)
                elif token == '-':
                    stack.append(a - b)
                elif token == '*':
                    stack.append(a * b)
                elif token == '/':
                    stack.append(a / b)
        return stack[0]

    expr = expr.replace(' ', '')
    rpn = shunting_yard(expr)
    return evaluate_rpn(rpn)

class Token:
    """Represents a token in the expression."""
    NUMBER, PLUS, MINUS, MUL, DIV, LPAREN, RPAREN, EOF = ('NUMBER', 'PLUS', 'MINUS', 'MUL', 'DIV', 'LPAREN', 'RPAREN', 'EOF')

    def __init__(self, type_, value):
        self.type = type_
        self.value = value

class Lexer:
    """Lexical analyzer for the arithmetic expression."""

    def __init__(self, text):
        self.text = text.replace(' ', '')
        self.position = 0
        self.current_char = self.text[self.position] if self.text else None

    def error(self):
        raise Exception("Invalid character")

    def advance(self):
        """Advance the `position` pointer and update `current_char`."""
        self.position += 1
        self.current_char = self.text[self.position] if self.position < len(self.text) else None

    def number(self):
        """Return a NUMBER token."""
        result = ''
        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            result += self.current_char
            self.advance()
        return Token(Token.NUMBER, float(result))

    def get_next_token(self):
        """Tokenize the input string."""
        while self.current_char is not None:
            if self.current_char.isdigit() or self.current_char == '.':
                return self.number()
            if self.current_char == '+':
                self.advance()
                return Token(Token.PLUS, '+')
            if self.current_char == '-':
                self.advance()
                return Token(Token.MINUS, '-')
            if self.current_char == '*':
                self.advance()
                return Token(Token.MUL, '*')
            if self.current_char == '/':
                self.advance()
                return Token(Token.DIV, '/')
            if self.current_char == '(':
                self.advance()
                return Token(Token.LPAREN, '(')
            if self.current_char == ')':
                self.advance()
                return Token(Token.RPAREN, ')')
            self.error()
        return Token(Token.EOF, None)

class Parser:
    """Parses the tokens produced by the Lexer and evaluates the expression."""

    def __init__(self, lexer):
        self.lexer = lexer
        self.current_token = lexer.get_next_token()

    def error(self):
        raise Exception("Invalid syntax")

    def eat(self, token_type):
        """Consume the current token if it matches the expected type."""
        if self.current_token.type == token_type:
            self.current_token = self.lexer.get_next_token()
        else:
            self.error()

    def factor(self):
        """Parse a factor (number or expression in parentheses)."""
        token = self.current_token
        if token.type == Token.NUMBER:
            self.eat(Token.NUMBER)
            return token.value
        elif token.type == Token.LPAREN:
            self.eat(Token.LPAREN)
            result = self.expr()
            self.eat(Token.RPAREN)
            return result

    def term(self):
        """Parse a term (factors combined by * or /)."""
        result = self.factor()
        while self.current_token.type in (Token.MUL, Token.DIV):
            token = self.current_token
            if token.type == Token.MUL:
                self.eat(Token.MUL)
                result *= self.factor()
            elif token.type == Token.DIV:
                self.eat(Token.DIV)
                divisor = self.factor()
                if divisor == 0:
                    self.error()  # Handle division by zero
                result /= divisor
        return result

    def expr(self):
        """Parse an expression (terms combined by + or -)."""
        result = self.term()
        while self.current_token.type in (Token.PLUS, Token.MINUS):
            token = self.current_token
            if token.type == Token.PLUS:
                self.eat(Token.PLUS)
                result += self.term()
            elif token.type == Token.MINUS:
                self.eat(Token.MINUS)
                result -= self.term()
        return result

def evaluate(expr: str) -> float:
    """Evaluates a given arithmetic expression respecting standard operator precedence."""
    lexer = Lexer(expr)
    parser = Parser(lexer)
    return parser.expr()

class ShuntingYard:
    """An implementation of the Shunting Yard algorithm to evaluate arithmetic expressions."""

    def __init__(self, expression: str):
        self.expression = expression.replace(' ', '')
        self.output = []
        self.operators = []
        self.precedence = {'+': 1, '-': 1, '*': 2, '/': 2}

    def is_operator(self, c: str) -> bool:
        return c in self.precedence

    def precedence_of(self, op: str) -> int:
        return self.precedence.get(op, 0)

    def process_operator(self, operator: str):
        while (self.operators and self.operators[-1] != '(' and
               self.precedence_of(operator) <= self.precedence_of(self.operators[-1])):
            self.output.append(self.operators.pop())
        self.operators.append(operator)

    def evaluate_rpn(self) -> float:
        stack = []
        for token in self.output:
            if token in self.precedence:
                b = stack.pop()
                a = stack.pop()
                if token == '+':
                    stack.append(a + b)
                elif token == '-':
                    stack.append(a - b)
                elif token == '*':
                    stack.append(a * b)
                elif token == '/':
                    if b == 0:
                        raise Exception("Division by zero")
                    stack.append(a / b)
            else:
                stack.append(float(token))
        return stack[0]

    def parse(self):
        i = 0
        while i < len(self.expression):
            char = self.expression[i]
            if char.isdigit() or char == '.':
                num = []
                while i < len(self.expression) and (self.expression[i].isdigit() or self.expression[i] == '.'):
                    num.append(self.expression[i])
                    i += 1
                self.output.append(''.join(num))
                continue
            elif char == '(':
                self.operators.append(char)
            elif char == ')':
                while self.operators and self.operators[-1] != '(':
                    self.output.append(self.operators.pop())
                self.operators.pop()  # Remove the '('
            elif self.is_operator(char):
                self.process_operator(char)
            i += 1

        while self.operators:
            self.output.append(self.operators.pop())

    def evaluate(self) -> float:
        self.parse()
        return self.evaluate_rpn()

def evaluate(expr: str) -> float:
    """Evaluates a given arithmetic expression using the Shunting Yard algorithm."""
    parser = ShuntingYard(expr)
    return parser.evaluate()
